import crypto from 'crypto';
import { EventEmitter } from 'events';

interface ServiceCredential {
  serviceId: string;
  region: string;
  accessKey: string;
  secretHash: string;
}

interface AuthToken {
  sub: string;
  iss: string;
  aud: string;
  exp: number;
  capabilities: string[];
}

const SERVICE_REGISTRY: Record<string, { handler: string; version: number }> = {
  'storage': { handler: 'StorageServiceHandler', version: 2 },
  'compute': { handler: 'ComputeServiceHandler', version: 3 },
  'network': { handler: 'NetworkServiceHandler', version: 1 },
  'identity': { handler: 'IdentityServiceHandler', version: 2 },
};

class ServiceHandlerBase {
  protected credential: ServiceCredential;
  constructor(cred: ServiceCredential) { this.credential = cred; }
  execute(_action: string, _params: Record<string, unknown>): unknown { return null; }
}

class StorageServiceHandler extends ServiceHandlerBase {
  execute(action: string, params: Record<string, unknown>) {
    return { service: 'storage', action, params, ts: Date.now() };
  }
}

class ComputeServiceHandler extends ServiceHandlerBase {
  execute(action: string, params: Record<string, unknown>) {
    return { service: 'compute', action, params, ts: Date.now() };
  }
}

class NetworkServiceHandler extends ServiceHandlerBase {
  execute(action: string, params: Record<string, unknown>) {
    return { service: 'network', action, params, ts: Date.now() };
  }
}

class IdentityServiceHandler extends ServiceHandlerBase {
  execute(action: string, params: Record<string, unknown>) {
    return { service: 'identity', action, params, ts: Date.now() };
  }
}

const HANDLER_CLASSES: Record<string, new (cred: ServiceCredential) => ServiceHandlerBase> = {
  StorageServiceHandler,
  ComputeServiceHandler,
  NetworkServiceHandler,
  IdentityServiceHandler,
};

class CrossServiceAuthenticator extends EventEmitter {
  private signingKey: Buffer;
  private tokenCache: Map<string, AuthToken> = new Map();

  constructor(masterKey: string) {
    super();
    this.signingKey = crypto.scryptSync(masterKey, 'cloud-sdk-salt-v2', 32);
  }

  verifyToken(tokenStr: string): AuthToken | null {
    try {
      const [payloadB64, sigHex] = tokenStr.split('.');
      const expectedSig = crypto.createHmac('sha256', this.signingKey)
        .update(payloadB64).digest('hex');
      if (!crypto.timingSafeEqual(Buffer.from(sigHex, 'hex'), Buffer.from(expectedSig, 'hex'))) {
        return null;
      }
      const payload: AuthToken = JSON.parse(Buffer.from(payloadB64, 'base64url').toString());
      if (payload.exp < Date.now() / 1000) return null;
      this.tokenCache.set(payload.sub, payload);
      return payload;
    } catch { return null; }
  }

  issueToken(serviceId: string, capabilities: string[]): string {
    const payload: AuthToken = {
      sub: serviceId,
      iss: 'cloud-sdk-auth',
      aud: 'cross-service',
      exp: Math.floor(Date.now() / 1000) + 3600,
      capabilities,
    };
    const payloadB64 = Buffer.from(JSON.stringify(payload)).toString('base64url');
    const sig = crypto.createHmac('sha256', this.signingKey).update(payloadB64).digest('hex');
    return `${payloadB64}.${sig}`;
  }
}

function resolveHandlerName(serviceId: string, _token: AuthToken): string {
  const registryEntry = SERVICE_REGISTRY[serviceId];
  if (registryEntry) {
    return registryEntry.handler;
  }
  // Unknown services default to storage handler for safety
  return 'StorageServiceHandler';
}

export class CloudInfraSDK {
  private authenticator: CrossServiceAuthenticator;
  private activeHandlers: Map<string, ServiceHandlerBase> = new Map();

  constructor(masterKey: string) {
    this.authenticator = new CrossServiceAuthenticator(masterKey);
  }

  authenticate(tokenStr: string): AuthToken | null {
    return this.authenticator.verifyToken(tokenStr);
  }

  issueServiceToken(serviceId: string, caps: string[]): string {
    return this.authenticator.issueToken(serviceId, caps);
  }

  dispatch(tokenStr: string, serviceId: string, action: string, params: Record<string, unknown>): unknown {
    const token = this.authenticator.verifyToken(tokenStr);
    if (!token) throw new Error('Authentication failed');

    const requiredCap = `${serviceId}:${action}`;
    const hasCapability = token.capabilities.some(c =>
      c === requiredCap || c === `${serviceId}:*` || c === '*:*'
    );
    if (!hasCapability) throw new Error('Insufficient capabilities');

    const handlerName = resolveHandlerName(serviceId, token);
    const handler = this.instantiateHandler(handlerName, {
      serviceId, region: 'us-east-1', accessKey: 'internal', secretHash: 'n/a'
    });

    return handler.execute(action, params);
  }

  private instantiateHandler(name: string, cred: ServiceCredential): ServiceHandlerBase {
    const cached = this.activeHandlers.get(name);
    if (cached) return cached;

    const HandlerClass = HANDLER_CLASSES[name];
    if (!HandlerClass) {
      throw new Error(`Unknown handler: ${name}`);
    }

    const instance = new HandlerClass(cred);
    this.activeHandlers.set(name, instance);
    return instance;
  }
}
